class Solution {
    map<pair<int, int>, vector<pair<pair<int, int>, int>>> graph;
    set<pair<int, int>> visited;
    pair<int, int> target;
    bool found = false;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    char direction[4] = {'U', 'D', 'L', 'R'};
    char back[4] = {'D', 'U', 'R', 'L'};

    void explore(GridMaster& master, int r, int c) {
        pair<int, int> here = {r, c};
        visited.insert(here);
        if (master.isTarget()) { found = true; target = here; }
        for (int d = 0; d < 4; ++d) {
            pair<int, int> next = {r + dr[d], c + dc[d]};
            if (!master.canMove(direction[d])) continue;
            int cost = master.move(direction[d]);
            graph[here].push_back({next, cost});
            if (!visited.count(next)) explore(master, next.first, next.second);
            int returnCost = master.move(back[d]);
            graph[next].push_back({here, returnCost});
        }
    }
public:
    int findShortestPath(GridMaster& master) {
        graph.clear(); visited.clear(); found = false;
        explore(master, 0, 0);
        if (!found) return -1;
        using State = pair<int, pair<int, int>>;
        priority_queue<State, vector<State>, greater<State>> pq;
        map<pair<int, int>, int> distance;
        distance[{0, 0}] = 0;
        pq.push({0, {0, 0}});
        while (!pq.empty()) {
            State state = pq.top(); pq.pop();
            int cost = state.first;
            auto here = state.second;
            if (cost != distance[here]) continue;
            if (here == target) return cost;
            for (const auto& edge : graph[here]) {
                auto next = edge.first;
                int candidate = cost + edge.second;
                if (!distance.count(next) || candidate < distance[next]) {
                    distance[next] = candidate;
                    pq.push({candidate, next});
                }
            }
        }
        return -1;
    }
};
